EXPLAIN ANALYZE SELECT student.* FROM students student LEFT JOIN classes classEntity ON classEntity.id = student."classId" WHERE (COALESCE(student."firstName", '') || ' ' || COALESCE(student."lastName", '') || ' ' || COALESCE(student."studentNumber", '') || ' ' || COALESCE(student."contactNumber", student."phoneNumber", '')) ILIKE '%fari%' ORDER BY student."lastName" ASC, student."firstName" ASC LIMIT 50;
